/* Brisa · pruebas de la lógica de fechas. Ejecutar: node docs/requirements/brisa/prototype/logic.test.js
   Esperado según INVENTARIO-BRISA.md: vectores V1–V10 y criterios AC1–AC7 (§13.1), casos C y N (§11, §13.10, §13.11). «Hoy» = 2026-10-18 salvo indicación. */
const assert = require("node:assert/strict");
const L = require("./logic.js");
let ok = 0, bad = 0;
const t = (name, fn) => { try { fn(); ok++; console.log("OK   " + name); } catch (e) { bad++; console.log("FALLA " + name + "  -> " + e.message); } };
const Z = "America/Costa_Rica", TODAY = "2026-10-18";
const T = (o) => Object.assign({ id: String(Math.random()), title: "t", details: "", priority: "MEDIUM", colorHex: "#DDE8D5", completed: false, completedAt: null, dueDate: null, deletedAt: null, createdAt: 1 }, o);
const eff = (o, today = TODAY) => L.effectiveDate(T(o), today, Z);
const day = (d) => "2026-10-" + d;
// ── Vectores V1–V10 (§13.1) ──
const V = [
  ["V1", { scheduledDate: day(15) }, "15", true], ["V2", { scheduledDate: day(15), dueDate: day(20) }, "18", false], ["V3", { scheduledDate: day(15), dueDate: day(18) }, "18", false],
  ["V4", { scheduledDate: day(15), dueDate: day(17) }, "17", true], ["V5", { scheduledDate: day(20), dueDate: day(25) }, "20", false], ["V6", { scheduledDate: day(20), dueDate: day(17) }, "20", true],
  ["V7", { scheduledDate: day(15), dueDate: day(20), completed: true, completedAt: "2026-10-18T15:00:00Z" }, "18", false], ["V8", { scheduledDate: day(15), dueDate: day(20), completed: true, completedAt: "2026-10-16T15:00:00Z" }, "16", false],
  ["V9", { scheduledDate: day(15), dueDate: day(20), completed: true, completedAt: null }, "15", false], ["V10", { scheduledDate: day(15), completed: true, completedAt: "2026-10-18T15:00:00Z" }, "15", false],
];
for (const [id, o, d, v] of V) t(id + " · día efectivo 10-" + d + ", " + (v ? "vencida" : "no vencida"), () => { assert.equal(eff(o), day(d)); assert.equal(L.isOverdue(T(o), TODAY, Z), v); });
// ── Criterios de aceptación (§13.1) ──
t("AC1 · a las 00:00 locales, la tarea abierta con límite ≥ hoy avanza al día nuevo sin escribir nada (hoy 18 → 19)", () => { const x = T({ scheduledDate: day(18), dueDate: day(21) }); assert.equal(L.effectiveDate(x, day(18), Z), day(18)); assert.equal(L.effectiveDate(x, day(19), Z), day(19)); assert.equal(x.scheduledDate, day(18), "ScheduledDate no se reescribe"); });
t("AC2 · avanza cada día hasta el día de su fecha límite (P=15, L=20: se ve el 15, 16, 17, 18, 19 y 20)", () => { const x = T({ scheduledDate: day(15), dueDate: day(20) }); assert.deepEqual([15, 16, 17, 18, 19, 20].map((h) => L.effectiveDate(x, day(h), Z)), [15, 16, 17, 18, 19, 20].map(day)); });
t("AC3 · la noche siguiente a su fecha límite deja de moverse: queda en el día de la fecha límite, vencida (hoy 21 → día 20)", () => { const x = T({ scheduledDate: day(15), dueDate: day(20) }); assert.equal(L.effectiveDate(x, day(21), Z), day(20)); assert.equal(L.effectiveDate(x, day(25), Z), day(20)); assert.equal(L.isOverdue(x, day(21), Z), true); });
t("AC4 · sin fecha límite nunca se mueve", () => { const x = T({ scheduledDate: day(15) }); for (const h of [15, 18, 25]) assert.equal(L.effectiveDate(x, day(h), Z), day(15)); });
t("AC5 · nunca queda «atrás y perdida» en un día pasado mientras su fecha límite sea ≥ hoy (barrido de 60 días)", () => { for (let p = 1; p <= 15; p++) for (let l = p; l <= 30; l++) for (let h = 1; h <= 30; h++) { const x = T({ scheduledDate: "2026-10-" + String(p).padStart(2, "0"), dueDate: "2026-10-" + String(l).padStart(2, "0") }); const today = "2026-10-" + String(h).padStart(2, "0"); const e = L.effectiveDate(x, today, Z); if (x.dueDate >= today) assert.ok(e >= today || x.scheduledDate >= today, `P${p} L${l} hoy ${h}`); } });
t("AC6 · si la persona no abre la app varios días, al volver la tarea aparece en hoy (no en los días que faltó) — N04", () => { const x = T({ scheduledDate: day(15), dueDate: day(20) }); assert.equal(L.effectiveDate(x, day(19), Z), day(19)); assert.notEqual(L.effectiveDate(x, day(19), Z), day(16)); });
t("AC7 · una tarea hecha no se mueve más: queda en el día en que se marcó (N03)", () => { const x = T({ scheduledDate: day(15), dueDate: day(20), completed: true, completedAt: "2026-10-18T20:00:00Z" }); for (const h of [18, 19, 21]) assert.equal(L.effectiveDate(x, day(h), Z), day(18)); });
// ── Casos de paridad y nuevos ──
t("C03 · abierta P=17 sin límite: vencida, sigue en el 17, no se reprograma", () => { const x = T({ scheduledDate: day(17) }); assert.equal(L.isOverdue(x, TODAY, Z), true); assert.equal(L.effectiveDate(x, TODAY, Z), day(17)); });
t("C04/C23 · P=18 (sin límite, o con límite 18): no vencida; en HOY", () => { assert.equal(L.isOverdue(T({ scheduledDate: day(18) }), TODAY, Z), false); assert.equal(L.isOverdue(T({ scheduledDate: day(18), dueDate: day(18) }), TODAY, Z), false); });
t("C06 · P=15, L=20: en HOY (18) y en Fechas límite; ScheduledDate intacta", () => { const x = T({ scheduledDate: day(15), dueDate: day(20) }); assert.equal(eff(x), day(18)); assert.equal(L.overdue([x], TODAY, Z).length, 0); assert.equal(L.deadlines([x], TODAY).length, 1); });
t("C07 · P=16, L=18: hoy 18 en HOY; hoy 19 → día efectivo 18, en Vencidas y «vencida» en Fechas límite", () => { const x = T({ scheduledDate: day(16), dueDate: day(18) }); assert.equal(L.effectiveDate(x, day(18), Z), day(18)); assert.equal(L.effectiveDate(x, day(19), Z), day(18)); assert.equal(L.isOverdue(x, day(19), Z), true); assert.equal(L.deadlines([x], day(19)).length, 1); });
t("C08/C09 · hecha: no vencida; con límite pasado no aparece en Fechas límite", () => { assert.equal(L.deadlines([T({ scheduledDate: day(14), dueDate: day(16), completed: true })], TODAY).length, 0); assert.equal(L.deadlines([T({ scheduledDate: day(15), dueDate: day(20), completed: true })], TODAY).length, 1); });
t("C10 / N02 · reabrir (hecha, P=14, L=25): aparece de inmediato en HOY, sin esperar al siguiente arranque", () => { assert.equal(eff({ scheduledDate: day(14), dueDate: day(25), completed: false }), day(18)); });
t("C11 · reabrir hecha P=14 sin límite: abierta y de inmediato en Vencidas", () => { assert.equal(L.isOverdue(T({ scheduledDate: day(14) }), TODAY, Z), true); });
t("C21 · orden de Vencidas por (límite ?? día efectivo) ↑ y prioridad ↓: V2, V3, V4, V1", () => { const a = [T({ id: "V1", scheduledDate: day(15), priority: "LOW" }), T({ id: "V2", scheduledDate: day(20), dueDate: day(14) }), T({ id: "V3", scheduledDate: day(15), priority: "HIGH" }), T({ id: "V4", scheduledDate: day(12), dueDate: day(15) })]; assert.deepEqual(L.overdue(a, TODAY, Z).map((x) => x.id), ["V2", "V3", "V4", "V1"]); });
t("C22 · orden de Fechas límite: abiertas antes que hechas, límite ↑, prioridad ↓: F1, F4, F2, F3, F5", () => { const a = [T({ id: "F1", dueDate: day(17), priority: "LOW", scheduledDate: day(10) }), T({ id: "F2", dueDate: day(20), priority: "HIGH", scheduledDate: day(10) }), T({ id: "F3", dueDate: day(20), priority: "LOW", scheduledDate: day(10) }), T({ id: "F4", dueDate: day(19), priority: "MEDIUM", scheduledDate: day(10) }), T({ id: "F5", dueDate: day(19), completed: true, scheduledDate: day(10) })]; assert.deepEqual(L.deadlines(a, TODAY).map((x) => x.id), ["F1", "F4", "F2", "F3", "F5"]); });
t("C26 / N19 · frontera de zona: 23:30 del 18 en Costa Rica (05:30 UTC del 19) → hoy = 18; con zona Nueva York → hoy = 19", () => { const now = new Date("2026-10-19T05:30:00Z"); assert.equal(L.todayInZone("America/Costa_Rica", now), "2026-10-18"); assert.equal(L.todayInZone("America/New_York", now), "2026-10-19"); assert.equal(L.todayInZone("UTC", now), "2026-10-19"); });
t("N21 · una zona inválida («Mars/Olympus») se detecta (la interfaz no la guarda)", () => { assert.throws(() => L.todayInZone("Mars/Olympus")); });
t("N05/N06 · P=15, L=20, hoy 21 → en el 20 vencida y no avanza; sin límite hoy 19 → sigue en el 15", () => { assert.equal(L.effectiveDate(T({ scheduledDate: day(15), dueDate: day(20) }), day(21), Z), day(20)); assert.equal(L.effectiveDate(T({ scheduledDate: day(15) }), day(19), Z), day(15)); });
t("N07 · P=15, L=25 y se cambia el día a 22: hasta el 21 no aparece en hoy; el 22 aparece en el 22; el 23 se mueve al 23", () => { const x = T({ scheduledDate: day(22), dueDate: day(25) }); assert.equal(L.effectiveDate(x, day(21), Z), day(22)); assert.equal(L.effectiveDate(x, day(22), Z), day(22)); assert.equal(L.effectiveDate(x, day(23), Z), day(23)); });
t("N08/N26/N28 · día después de la fecha límite se rechaza al crear o modificar, con el mensaje de Brisa", () => { for (const o of [{ scheduledDate: day(18), dueDate: day(17) }, { scheduledDate: day(18), dueDate: day(16) }]) { const r = L.validateTask(T(o)); assert.equal(r.ok, false); assert.equal(r.code, "brisa.task.day_after_deadline"); assert.equal(r.message, L.MSG_ORDER); } });
t("N27 · guardada P=15, L=25 (el editor muestra el 18): L→17 es válido (15 ≤ 17); cambiar el día a 26 se rechaza", () => { assert.equal(L.validateTask(T({ scheduledDate: day(15), dueDate: day(17) })).ok, true); assert.equal(L.validateTask(T({ scheduledDate: day(26), dueDate: day(25) })).ok, false); });
t("N09/N10 · rescate: con límite vencida solo cambiar la fecha límite la saca de Vencidas; sin límite basta mover el día a hoy", () => { const a = T({ scheduledDate: day(15), dueDate: day(17) }); assert.equal(L.isOverdue(a, TODAY, Z), true); assert.equal(L.isOverdue(T({ scheduledDate: day(15), dueDate: day(25) }), TODAY, Z), false); assert.equal(L.isOverdue(T({ scheduledDate: day(18) }), TODAY, Z), false); });
t("N15/C15 · título en blanco no se guarda; C14 · alta mínima válida con solo el título", () => { assert.equal(L.validateTask(T({ title: "   ", scheduledDate: TODAY })).ok, false); assert.equal(L.validateTask({ title: "  Comprar pan  ", scheduledDate: TODAY, colorHex: "#DDE8D5" }).ok, true); });
t("N18 · título de 150 / 151 y notas de 2000 / 2001 caracteres: 150 y 2000 se aceptan; 151 y 2001 → error claro, sin truncar", () => { const base = { scheduledDate: TODAY }; assert.equal(L.validateTask({ ...base, title: "a".repeat(150) }).ok, true); assert.equal(L.validateTask({ ...base, title: "a".repeat(151) }).code, "brisa.task.title_too_long"); assert.equal(L.validateTask({ ...base, title: "x", details: "b".repeat(2000) }).ok, true); assert.equal(L.validateTask({ ...base, title: "x", details: "b".repeat(2001) }).code, "brisa.task.notes_too_long"); });
t("Color: solo #RRGGBB (R5); formato inválido se rechaza", () => { assert.equal(L.validateTask({ title: "x", scheduledDate: TODAY, colorHex: "rojo" }).code, "brisa.task.color_invalid"); });
t("N17 · búsqueda «reunion» encuentra «Reunión semanal» (título) y «REUNIÓN» (notas); no las eliminadas", () => { const a = [T({ title: "Reunión semanal" }), T({ title: "Otra", details: "REUNIÓN con Ana" }), T({ title: "Reunión vieja", deletedAt: "2026-10-01T00:00:00Z" }), T({ title: "Comprar pan" })]; assert.equal(L.search(a, "reunion").length, 2); assert.equal(L.search(a, "").length, 0); });
t("N24/C32 · singular correcto: «1 pendiente», «1 hecha», «2 pendientes»", () => { assert.equal(L.plural(1, "pendiente", "pendientes"), "1 pendiente"); assert.equal(L.plural(1, "hecha", "hechas"), "1 hecha"); assert.equal(L.plural(2, "pendiente", "pendientes"), "2 pendientes"); });
t("Determinismo (C30): calcular dos veces da lo mismo y no escribe", () => { const x = T({ scheduledDate: day(15), dueDate: day(20) }); const a = L.effectiveDate(x, TODAY, Z), b = L.effectiveDate(x, TODAY, Z); assert.equal(a, b); assert.equal(x.scheduledDate, day(15)); });
console.log("\n" + ok + " pruebas en verde, " + bad + " con fallas."); process.exit(bad ? 1 : 0);
